"""Unit F: Advanced Python."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("genexp", "medium", "What is printed?", "g = (x * x for x in range(3))\nprint(sum(g), sum(g), type(g).__name__)", "5 0 generator", ["5 5 generator", "5 0 list", "TypeError"], "A generator expression is consumed once; the second sum sees it exhausted."),
        M("genexp", "medium", "Why prefer sum(x * x for x in data) over sum([x * x for x in data]) for large data?", "The generator version never builds the whole intermediate list in memory", ["It is always faster for small data", "The list version is a syntax error", "It sorts the data first"], "Generator expressions yield items lazily, keeping memory use constant."),
        O("regex", "medium", "What is printed?", "import re\nm = re.search(r'(\\d+)-(\\d+)', 'ticket 12-345 ok')\nprint(m.group(0), m.group(2), m.span(), re.findall(r'\\d', 'a1b22'))", "12-345 345 (7, 13) ['1', '2', '2']", ["12-345 12 (7, 13) ['1', '22']", "12 345 (7, 13) ['1', '2', '2']", "12-345 345 (7, 12) ['1', '2', '2']"], "group(0) is the whole match, group(2) the second capture, span gives start and end indexes; findall with a single-digit pattern returns each digit."),
        O("regex", "hard", "What is printed?", "import re\ns = '<b>x</b><b>y</b>'\nprint(re.findall(r'<b>(.*)</b>', s), re.findall(r'<b>(.*?)</b>', s))", "['x</b><b>y'] ['x', 'y']", ["['x', 'y'] ['x', 'y']", "['x</b><b>y'] ['x</b><b>y']", "['x', 'y'] ['x</b><b>y']"], "`.*` is greedy and matches as much as possible; `.*?` is lazy and stops at the first closing tag."),
        O("collections-module", "medium", "What is printed?", "from collections import namedtuple, OrderedDict\nP = namedtuple('P', 'x y')\np = P(1, 2)\nprint(p.x, p[1], p._replace(x=9), p._asdict())", "1 2 P(x=9, y=2) {'x': 1, 'y': 2}", ["1 2 P(x=9, y=2) OrderedDict([('x', 1), ('y', 2)])", "1 1 P(x=9, y=2) {'x': 1, 'y': 2}", "1 2 (9, 2) {'x': 1, 'y': 2}"], "namedtuple gives named field access and tuple behaviour; _replace returns a modified copy. In Python 3.8+ _asdict returns a plain dict.", py="3.8+"),
        M("collections-module", "easy", "Which collections class is best for a queue with fast appends and pops at both ends?", "deque", ["list", "tuple", "frozenset"], "deque offers O(1) append/pop on either end; list.pop(0) is O(n)."),
        O("counter-defaultdict-deque", "medium", "What is printed?", "from collections import Counter, defaultdict, deque\nd = defaultdict(list)\nd['a'].append(1)\nq = deque([1, 2, 3], maxlen=3)\nq.append(4)\nprint(dict(d), list(q), (Counter('aab') + Counter('bb')).most_common(1))", "{'a': [1]} [2, 3, 4] [('b', 3)]", ["{'a': [1]} [1, 2, 3, 4] [('b', 3)]", "KeyError [2, 3, 4] [('b', 3)]", "{'a': [1]} [2, 3, 4] [('a', 2)]"], "defaultdict creates the missing list; a deque with maxlen=3 drops the oldest item when a fourth arrives; adding Counters sums counts per key (a:2, b:1+2=3), so b is the most common."),
        M("counter-defaultdict-deque", "medium", "What does defaultdict(int)['x'] return for a missing key?", "0, and the key x is inserted with that value", ["KeyError", "None, and nothing is inserted", "An empty string"], "The factory is called to create and store the default."),
        O("itertools", "medium", "What is printed?", "import itertools as it\nprint(list(it.islice(it.count(5), 3)), list(it.chain([1], [2, 3])), list(it.product('ab', [0, 1]))[:3], list(it.combinations([1, 2, 3], 2)))", "[5, 6, 7] [1, 2, 3] [('a', 0), ('a', 1), ('b', 0)] [(1, 2), (1, 3), (2, 3)]", ["[5, 6, 7] [1, 2, 3] [('a', 0), ('b', 0), ('a', 1)] [(1, 2), (1, 3), (2, 3)]", "[5, 6, 7] [[1], [2, 3]] [('a', 0), ('a', 1), ('b', 0)] [(1, 2), (1, 3), (2, 3)]", "[5, 6, 7] [1, 2, 3] [('a', 0), ('a', 1), ('b', 0)] [(1, 2), (2, 3), (1, 3)]"], "count is infinite so islice limits it; chain flattens one level; product varies the last iterable fastest; combinations emit in lexicographic order."),
        M("itertools", "medium", "Which itertools function groups consecutive equal keys?", "groupby (and its input must be sorted by the key to group all equal items)", ["chain", "cycle", "accumulate"], "groupby only groups adjacent items with the same key, so sort first when you want total groups."),
        O("functools", "medium", "What is printed?", "from functools import lru_cache, partial\ncalls = []\n@lru_cache(maxsize=None)\ndef f(n):\n    calls.append(n)\n    return n * 2\n\nf(1); f(1); f(2)\npower2 = partial(pow, exp=2) if False else partial(pow, 2)\nprint(calls, power2(5))", "[1, 2] 32", ["[1, 1, 2] 32", "[1, 2] 25", "[1, 2] 10"], "lru_cache skips the second call with the same argument; partial(pow, 2) fixes the base, so power2(5) is 2**5."),
        M("functools", "medium", "What does functools.lru_cache require of the decorated function's arguments?", "They must be hashable", ["They must be integers", "They must be sorted", "They must be mutable"], "The cache stores results in a dict keyed by the arguments."),
        O("pathlib-adv", "medium", "What is printed?", "from pathlib import Path\nd = Path('/tmp/pl_demo')\nd.mkdir(exist_ok=True)\n(d / 'a.txt').write_text('hi')\n(d / 'b.log').write_text('yo!')\nprint(sorted(p.name for p in d.glob('*.txt')), (d / 'b.log').read_text(), (d / 'b.log').stat().st_size)", "['a.txt'] yo! 3", ["['a.txt', 'b.log'] yo! 3", "['a.txt'] yo! 4", "['a.txt'] yo 3"], "glob('*.txt') matches only the .txt file; the file contains three characters ('yo!')."),
        M("pathlib-adv", "medium", "Which pathlib call is safest for creating nested directories without failing if they already exist?", "Path.mkdir(parents=True, exist_ok=True)", ["Shelling out to the mkdir command through the os module", "Path.touch()", "open(path, 'w')"], "parents=True creates missing parents and exist_ok=True avoids FileExistsError."),
        O("datetime", "medium", "What is printed?", "from datetime import datetime, timedelta, timezone\nd = datetime(2024, 2, 28, tzinfo=timezone.utc) + timedelta(days=2)\nprint(d.date(), d.strftime('%d/%m/%Y'), d.weekday())", "2024-03-01 01/03/2024 4", ["2024-02-30 30/02/2024 3", "2024-03-01 01/03/2024 3", "2024-03-01 03/01/2024 4"], "2024 is a leap year, so Feb 28 + 2 days is Mar 1 (a Friday: weekday() is 4, Monday is 0)."),
        M("datetime", "medium", "Which is the best practice for storing timestamps?", "Store timezone-aware UTC datetimes and convert to local time only for display", ["Store naive local times", "Store strings like '10/11/12'", "Store the time as the local clock hour only"], "Naive datetimes are ambiguous around DST changes and across regions."),
        O("json-module", "medium", "What is printed?", "import json\nprint(json.dumps({'b': 1, 'a': [1, 2]}, sort_keys=True), json.dumps('é'), json.dumps('é', ensure_ascii=False))", "{\"a\": [1, 2], \"b\": 1} \"\\u00e9\" \"é\"", ["{\"b\": 1, \"a\": [1, 2]} \"\\u00e9\" \"é\"", "{\"a\": [1, 2], \"b\": 1} \"é\" \"é\"", "{\"a\": [1, 2], \"b\": 1} \"\\u00e9\" \"\\u00e9\""], "sort_keys orders object keys; by default non-ASCII is escaped, ensure_ascii=False keeps it."),
        M("json-module", "medium", "Which Python value cannot be serialised by json.dumps without help?", "A set", ["A list", "A dict with string keys", "A float"], "Sets and custom objects raise TypeError; convert them (e.g. to a sorted list) or pass default=."),
        O("custom-sort-keys", "medium", "What is printed?", "people = [('bob', 25), ('amy', 30), ('cat', 25)]\nprint(sorted(people, key=lambda p: (-p[1], p[0])))", "[('amy', 30), ('bob', 25), ('cat', 25)]", ["[('bob', 25), ('cat', 25), ('amy', 30)]", "[('amy', 30), ('cat', 25), ('bob', 25)]", "[('cat', 25), ('bob', 25), ('amy', 30)]"], "A tuple key sorts by age descending (negated), then name ascending. sorted is stable."),
        M("custom-sort-keys", "hard", "How do you sort with a legacy two-argument comparison function in Python 3?", "Wrap it with functools.cmp_to_key", ["Pass cmp=func to sorted", "Define __sort__ on the list", "It is impossible"], "The cmp parameter was removed; cmp_to_key adapts an old-style comparator to a key function."),
        M("concurrency", "medium", "Which workload benefits most from threads in CPython?", "I/O-bound work such as network or disk waits", ["CPU-bound number crunching in pure Python", "Sorting a list in memory", "Computing hashes in a tight Python loop"], "Threads release the GIL while waiting on I/O, so waiting overlaps; CPU-bound Python code is serialised by the GIL."),
        M("concurrency", "medium", "What is a race condition?", "A bug where the result depends on the unpredictable timing of concurrent operations on shared state", ["A function that runs too slowly", "A loop that never terminates", "A syntax error in threaded code"], "Protect shared mutable state with locks, queues or by avoiding sharing."),
        M("threads-processes", "medium", "Why use multiprocessing for CPU-bound Python work?", "Each process has its own interpreter and GIL, so work runs on multiple cores", ["Processes share memory with no cost", "Processes start faster than threads", "Threads cannot run Python code"], "Processes avoid the GIL but pay for startup and for pickling data between them."),
        O("threads-processes", "medium", "What is printed?", "import threading\nresults = []\nlock = threading.Lock()\ndef work(n):\n    with lock:\n        results.append(n * n)\n\nts = [threading.Thread(target=work, args=(i,)) for i in range(4)]\nfor t in ts: t.start()\nfor t in ts: t.join()\nprint(sorted(results))", "[0, 1, 4, 9]", ["[0, 1, 2, 3]", "[]", "[9, 4, 1, 0]"], "join() waits for completion; the order threads append in is not guaranteed, so sort before printing."),
        O("async-await", "medium", "What is printed?", "import asyncio\nasync def f(n):\n    await asyncio.sleep(0)\n    return n * 2\n\nasync def main():\n    return await asyncio.gather(f(1), f(2), f(3))\n\nprint(asyncio.run(main()))", "[2, 4, 6]", ["[1, 2, 3]", "[<coroutine object>, ...]", "RuntimeError"], "gather runs the coroutines concurrently and returns results in the order passed."),
        M("async-await", "medium", "What happens if you call an async function without await?", "You get a coroutine object and the body does not run (Python warns that it was never awaited)", ["It runs synchronously to completion", "It runs in a new thread", "It raises SyntaxError"], "A coroutine only runs when awaited or scheduled on an event loop."),
        O("event-loop", "hard", "What is printed?", "import asyncio\nasync def a():\n    print('a1'); await asyncio.sleep(0); print('a2')\nasync def b():\n    print('b1'); await asyncio.sleep(0); print('b2')\n\nasync def main():\n    await asyncio.gather(a(), b())\n\nasyncio.run(main())", "a1\nb1\na2\nb2", ["a1\na2\nb1\nb2", "a1\nb1\nb2\na2", "b1\na1\nb2\na2"], "Tasks interleave at each await: a1, b1, then control returns to the loop and each resumes in turn."),
        M("event-loop", "medium", "Why does time.sleep(2) inside a coroutine hurt an async server?", "It blocks the whole event loop so no other coroutine can run; use await asyncio.sleep instead", ["It raises an error in async code", "It only affects the current coroutine", "It sleeps in a separate thread"], "The loop is single-threaded; blocking calls stall every task."),
        M("gil", "medium", "What does the GIL do in standard CPython?", "Lets only one thread execute Python bytecode at a time within a process", ["Locks files against writing", "Encrypts memory", "Limits recursion depth"], "It simplifies memory management but prevents CPU-bound threads from running Python code in parallel."),
        M("gil", "hard", "What is true of the experimental free-threaded build of CPython 3.13?", "It is an optional build with the GIL disabled; it is not the default and library support varies", ["It removed the GIL from all Python builds", "It makes the GIL stronger", "It only exists in Python 2"], "PEP 703 added an opt-in build (python3.13t). Always state the Python version and build when discussing GIL behaviour.", py="3.13+"),
        O("memory-management", "medium", "What is printed?", "import sys\nprint(sys.getsizeof([]) < sys.getsizeof(list(range(100))), sys.getsizeof(1) <= sys.getsizeof(2 ** 100))", "True True", ["False True", "True False", "False False"], "A bigger list takes more memory, and a huge int needs more space than a small one. (Exact sizes vary by version and platform, so compare rather than quote numbers.)"),
        M("memory-management", "medium", "How can a Python program leak memory despite garbage collection?", "By keeping references alive, e.g. unbounded caches, global lists, or listeners that are never removed", ["By using too many local variables", "By calling print()", "Python cannot leak memory"], "Collectors free only unreachable objects; reachable-but-unneeded data stays."),
        O("profiling", "medium", "What is printed?", "import timeit\nfast = timeit.timeit('x in s', setup='s = set(range(1000)); x = 999', number=2000)\nslow = timeit.timeit('x in l', setup='l = list(range(1000)); x = 999', number=2000)\nprint(fast < slow)", "True", ["False", "None", "TypeError"], "Set membership is O(1) on average, while scanning a 1000-element list for the last item is O(n)."),
        M("profiling", "medium", "What should you do before optimising a slow Python program?", "Measure with a profiler (e.g. cProfile) to find the real hotspot", ["Rewrite everything in a lower-level language", "Guess and micro-optimise loops", "Add threads"], "Profile first; most time is usually spent in a small part of the code."),
        O("adv-copying", "hard", "What is printed?", "import copy\nclass Box:\n    def __init__(self): self.items = [1]\n\na = Box()\nb = copy.copy(a)\nc = copy.deepcopy(a)\nb.items.append(2)\nprint(a.items, c.items, b.items is a.items)", "[1, 2] [1] True", ["[1] [1] False", "[1, 2] [1, 2] True", "[1] [1] True"], "copy.copy duplicates the object but shares its attributes; deepcopy duplicates attributes too."),
        O("adv-copying", "hard", "What is printed?", "import copy\na = [1]\na.append(a)\nb = copy.deepcopy(a)\nprint(b[1] is b, b[1] is a)", "True False", ["False False", "True True", "RecursionError"], "deepcopy keeps a memo of copied objects, so a self-referencing list is copied into a new self-referencing list without infinite recursion."),
        O("adv-iterators-generators", "hard", "What is printed?", "class Count:\n    def __init__(self, n): self.n, self.i = n, 0\n    def __iter__(self): return self\n    def __next__(self):\n        if self.i >= self.n: raise StopIteration\n        self.i += 1\n        return self.i\n\nc = Count(3)\nprint(list(c), list(c))", "[1, 2, 3] []", ["[1, 2, 3] [1, 2, 3]", "[1, 2, 3] None", "StopIteration"], "The object is its own iterator, so once exhausted a second pass yields nothing. Return a fresh iterator from __iter__ to allow re-iteration."),
        O("adv-iterators-generators", "medium", "What is printed?", "def take(it, n):\n    for _ in range(n):\n        yield next(it)\n\nprint(list(take(iter('abcdef'), 3)), list(take(iter('ab'), 1)))", "['a', 'b', 'c'] ['a']", ["['a', 'b', 'c'] ['a', 'b']", "['a', 'b', 'c'] []", "StopIteration"], "The generator stops after n items; a short source would raise RuntimeError in 3.7+ if next() hit StopIteration inside a generator."),
        O("adv-decorators-closures", "hard", "What is printed?", "def repeat(n):\n    def deco(fn):\n        def wrapper(*a):\n            return [fn(*a) for _ in range(n)]\n        return wrapper\n    return deco\n\n@repeat(2)\ndef hi(x): return x + 1\n\nprint(hi(1))", "[2, 2]", ["2", "[2]", "TypeError"], "A decorator with arguments is a factory: repeat(2) returns the real decorator."),
        O("adv-decorators-closures", "hard", "What is printed?", "import functools\ndef deco(fn):\n    @functools.wraps(fn)\n    def w(*a): return fn(*a)\n    return w\n\n@deco\ndef f(x):\n    'doc'\n    return x\n\nprint(f.__name__, f.__doc__)", "f doc", ["w None", "f None", "w doc"], "functools.wraps copies __name__ and __doc__ to the wrapper."),
        O("adv-context-managers", "medium", "What is printed?", "from contextlib import contextmanager\n@contextmanager\ndef tag(name):\n    print('<' + name + '>', end='')\n    try:\n        yield\n    finally:\n        print('</' + name + '>', end='')\n\nwith tag('b'):\n    print('x', end='')", "<b>x</b>", ["x<b></b>", "<b></b>x", "<b>x"], "@contextmanager turns a generator into a context manager: code before yield is __enter__, the finally block is __exit__."),
        M("adv-context-managers", "hard", "In a class-based context manager, what does returning True from __exit__ do?", "It suppresses the exception that occurred in the with block", ["It re-raises the exception", "It restarts the with block", "It closes the program"], "Returning a truthy value tells Python the exception was handled."),
    ]
